#!/usr/bin/env python3
"""Revision-scoped lease census and causal application service census.

Discovery evidence is lease scoped: internal clean sets hold low targets that
positively echoed themselves, external clean sets hold other responders, and a
canary self echo quarantines its whole lease.  Application rows only count when
their lease is usable, their target holds a clean role, and that role's earliest
causal witness is not later than the row's event.
"""
from common import addresses
from ledger import Ledger
from protocols import cached_signature

ICMP_ECHO, ICMP_ERROR, ICMP_TIMEOUT = 0, 1, 2
APP_OPEN, APP_CLOSED, APP_TIMEOUT = 0, 1, 2
ROW_ICMP, ROW_APP, ROW_TOMB = 0, 1, 2
ROLE_INTERNAL, ROLE_EXTERNAL = 0, 1


def new_services(service_order):
    return {name: [set(), set(), set(), set(), 0] for name in service_order}
#      index:      0    io      1   ic      2   eo      3   ec     4 errors


def _witness_best(table, address, moment):
    previous = table.get(address)
    if previous is None or moment < previous:
        table[address] = moment


def build(context, records, low):
    """Return (snapshots, per-request activity booleans) for every query."""
    leases = context['leases']
    kinds = context['services']
    service_order = context['service_order']
    ledger = Ledger(records)
    requests_by_query = {moment: [] for moment in context['queries']}
    for row in context['requests'].values():
        requests_by_query[row['at']].append(row)
    order = sorted(leases)

    snapshots = []
    activity = {}
    for moment in context['queries']:
        counts, live = ledger.at(moment)

        internal = {name: set() for name in order}
        external = {name: set() for name in order}
        witness_in = {name: {} for name in order}
        witness_out = {name: {} for name in order}
        alias = set()
        applications = []

        for detail in live:
            kind = detail[0]
            if kind == ROW_ICMP:
                _, lease, event, target, responder, result, is_canary = detail
                if is_canary:
                    # Only a positive canary self echo marks the lease aliased.
                    if result == ICMP_ECHO and responder == target:
                        alias.add(lease)
                    continue
                if result == ICMP_TIMEOUT or lease not in internal:
                    continue
                if result == ICMP_ECHO and responder == target:
                    internal[lease].add(responder)
                    _witness_best(witness_in[lease], responder, event)
                else:
                    external[lease].add(responder)
                    _witness_best(witness_out[lease], responder, event)
            elif kind == ROW_APP:
                applications.append(detail)

        state = {}
        clean_in = {}
        clean_out = {}
        conflicts = {}
        for name in order:
            row = leases[name]
            if not (row['start'] <= moment < row['end']):
                state[name] = 'inactive'
                clean_in[name] = clean_out[name] = conflicts[name] = frozenset()
                continue
            clash = internal[name] & external[name]
            if name in alias:
                state[name] = 'alias'
                clean_in[name] = clean_out[name] = frozenset()
            elif clash:
                state[name] = 'conflict'
                clean_in[name] = clean_out[name] = frozenset()
            else:
                state[name] = 'usable'
                clean_in[name] = internal[name]
                clean_out[name] = external[name]
            conflicts[name] = clash

        groups = {}
        unbound = 0
        for detail in applications:
            _, lease, event, target, service, attempt, result, payload = detail
            if state[lease] != 'usable':
                unbound += 1
                continue
            if target in clean_in[lease]:
                role = ROLE_INTERNAL
                witness = witness_in[lease].get(target)
            elif target in clean_out[lease]:
                role = ROLE_EXTERNAL
                witness = witness_out[lease].get(target)
            else:
                role = -1
                witness = None
            if witness is None or witness > event:
                unbound += 1
                continue
            key = (lease, target, service)
            group = groups.get(key)
            if group is None:
                group = groups[key] = [attempt, role, {}, 0, 0, 0]
            elif attempt > group[0]:
                group[0] = attempt
                group[2] = {}
                group[3] = group[4] = group[5] = 0
            if attempt != group[0]:
                continue
            if result == APP_OPEN:
                parsed = cached_signature(kinds[service], payload)
                if parsed is None:
                    group[3] += 1        # malformed latest-attempt identity
                else:
                    group[2][parsed] = group[2].get(parsed, 0) + 1
            elif result == APP_CLOSED:
                group[4] += 1
            else:
                group[5] += 1

        buckets = {}
        for (lease, target, service), group in groups.items():
            report = buckets.get(lease)
            if report is None:
                report = buckets[lease] = new_services(service_order)
            entry = report[service]
            bad, closed, timeouts, signatures = group[3], group[4], group[5], group[2]
            total = bad + closed + timeouts + sum(signatures.values())
            entry[4] += bad
            if closed == total:
                status = 1
            elif bad or timeouts or closed or len(signatures) != 1:
                status = -1
            else:
                status = 0
            if status < 0:
                continue
            index = 0 if group[1] == ROLE_INTERNAL else 2
            entry[index + status].add(target)

        lease_rows = []
        for name in order:
            status_name = state[name]
            inside = clean_in[name]
            outside = clean_out[name]
            if status_name == 'usable':
                unresolved = low[name] - inside - outside
                report = buckets.get(name)
            elif status_name == 'inactive':
                unresolved = set()
                report = None
            else:
                unresolved = low[name]
                report = None
            services_out = []
            for service in service_order:
                if report is not None:
                    entry = report[service]
                    internal_open, internal_closed = entry[0], entry[1]
                    external_closed = entry[3]
                    only = internal_open if outside and \
                        len(external_closed) == len(outside) else set()
                    errors = entry[4]
                    known = internal_open | internal_closed
                else:
                    internal_open = internal_closed = set()
                    only = set()
                    errors = 0
                    known = frozenset()
                services_out.append({
                    'id': service,
                    'internal_open': addresses(entry[0] if report is not None else ()),
                    'internal_closed': addresses(entry[1] if report is not None else ()),
                    'external_open': addresses(entry[2] if report is not None else ()),
                    'external_closed': addresses(entry[3] if report is not None else ()),
                    'internal_only': addresses(only),
                    'protocol_errors': errors})
                for address in known:
                    activity.setdefault((name, service, address), False)
            lease_rows.append({'lease': name, 'state': status_name,
                               'conflicts': addresses(conflicts[name]),
                               'internal': addresses(inside),
                               'external': addresses(outside),
                               'unresolved': addresses(unresolved),
                               'services': services_out})

        for row in requests_by_query[moment]:
            name = row['lease']
            address = row['address']
            yes = False
            if state[name] == 'usable' and address in clean_in[name]:
                report = buckets.get(name)
                if report is None:
                    yes = True
                else:
                    entry = report[row['service']]
                    yes = address not in entry[0] and address not in entry[1]
            activity[(name, row['service'], address)] = yes

        snapshots.append({'at': moment, 'ledger': counts,
                          'unbound_applications': unbound, 'leases': lease_rows})
    return snapshots, activity
